import duckdb
import json
import time
from datetime import datetime, timezone

DB = "/files/duckdb/ag4_spe_v2.duckdb"
RUN_ID = "AG4FINNHUB_" + datetime.now(timezone.utc).strftime("%Y%m%d%H%M%S")

def connect_w(path, tries=6, delay=0.4):
    last = None
    for i in range(tries):
        try:
            return duckdb.connect(path)
        except Exception as e:
            last = e
            if "lock" in str(e).lower() and i < tries - 1:
                time.sleep(delay * (2 ** i)); continue
            raise
    raise last

con = connect_w(DB)
for ddl in ["ALTER TABLE news_history ADD COLUMN IF NOT EXISTS provider VARCHAR",
            "ALTER TABLE news_history ADD COLUMN IF NOT EXISTS news_article_id VARCHAR"]:
    try: con.execute(ddl)
    except Exception: pass
try:
    con.execute("DELETE FROM news_finnhub_staging WHERE news_id IN (SELECT news_id FROM news_history)")
except Exception:
    pass

rows = []
try:
    rows = con.execute("SELECT news_id, symbol, company_name, provider, news_article_id, url, title, published_at, snippet, first_seen_at FROM news_finnhub_staging WHERE COALESCE(status,'PENDING')='PENDING' ORDER BY published_at DESC LIMIT 400").fetchall()
except Exception:
    rows = []

out = []
for r in rows:
    news_id, sym, name, provider, art, url, title, pub, snippet, fsa = r
    title = str(title or "").strip()
    snippet = str(snippet or "").strip() or title
    pubs = str(pub or "")
    payload = {"source": "finnhub", "title": title, "date": pubs, "provider": provider, "snippet": snippet, "content": snippet}
    out.append({"json": {
        "run_id": RUN_ID, "db_path": DB,
        "newsId": news_id, "symbol": sym, "company_name": name or sym, "companyName": name or sym, "isin": None,
        "source": "finnhub", "provider": provider, "newsArticleId": art, "reason": "finnhub",
        "url": url, "articleUrl": url, "articleCanonicalUrl": url, "canonicalUrl": url,
        "title": title, "articleTitle": title, "publishedAt": pubs, "snippet": snippet, "text": snippet,
        "firstSeenAt": str(fsa or datetime.now(timezone.utc).isoformat()),
        "_reason": "finnhub", "_runAI": True, "_articlesLoopReset": False,
        "llmInput": json.dumps(payload),
    }})
try: con.execute("CHECKPOINT")
except Exception: pass
con.close()
return out

